content.content:
1	/**
2	 * What a lesson *serves* — and the schema the in-house decks are written to.
3	 *
4	 * The content-source seam: `LessonContent` names its one arm with a `kind`
5	 * discriminant, dispatched exhaustively with a `never` default, so the
6	 * compiler refuses a dispatch that forgets a case. Task 6.2 deleted the
7	 * licensed-`.webm` arm and the 25 files it served; a lesson serves only an
8	 * in-house deck now.
9	 *
10	 * The deck schema's one non-structural demand is **retrieval**: a deck is
11	 * invalid unless the learner is asked to attempt something before the answer
12	 * is shown. A guideline would be honoured by the first deck and forgotten by
13	 * the twelfth; a schema rule is checked on every deck for free.
14	 */
15	
16	import {
17		type LessonSequenceEntry,
18		lessonEntryById,
19		parseLessonId,
20	} from "./lessonSequence";
21	import { lessons, specialRules, toneRules } from "./symbols";
22	
23	// ============================================================================
24	// The content union
25	// ============================================================================
26	
27	/**
28	 * The strangler is closed (task 6.2): the licensed video arm is gone, and a
29	 * lesson's content is always a deck. This is a plain object type now, not a
30	 * `|` of variants — but the `kind` discriminant and the `never` default in
31	 * `describeLessonContent` stay, because they're what makes the next content
32	 * source a compile error here rather than a silent fallthrough, exactly as
33	 * they did when this had two arms.
34	 */
35	export type LessonContent = {
36		readonly kind: "deck";
37		readonly deckPath: string;
38	};
39	
40	/**
41	 * Exhaustive dispatch over `LessonContent`. The `never` default is the point:
42	 * adding a second arm without handling it here is a compile error, which is
43	 * how every downstream dispatch is kept honest too.
44	 */
45	export function describeLessonContent(content: LessonContent): string {
46		switch (content.kind) {
47			case "deck":
48				return `deck ${content.deckPath}`;
49			default: {
50				// Narrows on `content.kind`, not `content` itself: with a single
51				// literal-object type (no `|`) rather than a union of variants,
52				// TypeScript only narrows the switched-on property to `never`
53				// here, not the whole object — so that's what a future arm's
54				// compile error has to hinge on.
55				const _never: never = content.kind;
56				return _never;
57			}
58		}
59	}
60	
61	// ============================================================================
62	// Asset paths
63	// ============================================================================
64	
65	/**
66	 * Public root under which every generated lesson asset lives. Includes the
67	 * app's deploy base path (`vite.config.ts`'s `base: "/thai-script/"`) —
68	 * every other asset URL in this codebase (`symbols.ts`'s `audioUrl` fields)
69	 * is hardcoded the same way, and a root that omits it 404s once the app is
70	 * actually served under that base, dev included.
71	 */
72	export const LESSON_ASSET_ROOT = "/thai-script/lessons";
73	
74	export type DeckPathResult =
75		| { readonly ok: true; readonly path: string }
76		| { readonly ok: false; readonly error: string };
77	
78	/**
79	 * The one place a filesystem/URL path is derived from a lesson id, and so the
80	 * one place the charset has to hold. Task 1.3 owns the containment check at
81	 * the generator's write boundary; this owns the charset.
82	 */
83	export function deckPathForLesson(
84		value: unknown,
85		key = "lessonId",
86	): DeckPathResult {
87		const parsed = parseLessonId(value, key);
88		if (!parsed.ok) return parsed;
89		return { ok: true, path: `${LESSON_ASSET_ROOT}/${parsed.id}/deck.json` };
90	}
91	
92	// ============================================================================
93	// Resolution — three states, and "unresolvable" never reads as "undeclared"
94	// ============================================================================
95	
96	/**
97	 * Lessons whose content is an in-house deck. The strangler grew this set one
98	 * band at a time from task 1.4's `lesson-01`; task 4.3 closed it — every
99	 * declared lesson is here, and no lesson resolves to the video arm any more.
100	 *
101	 * `lesson-sound-buckets` is deliberately absent: it has no `legacyNumber` in
102	 * `lessonSequence.ts`, and giving it one is a lesson-identity decision
103	 * (CONTEXT.md Rule 1 — the five-store hazard) that belongs with the task
104	 * that owns that migration, not a one-line addition here. Its deck is
105	 * committed and schema-valid (see `openingBand.test.ts`) but unreachable
106	 * from any route until that sequencing decision is made.
107	 */
108	export const DECK_LESSON_IDS: ReadonlySet<string> = new Set<string>([
109		"lesson-01",
110		"lesson-02",
111		"lesson-03",
112		"lesson-04",
113		"lesson-05",
114		// Phase 3's middle band.
115		"lesson-06",
116		"lesson-07",
117		"lesson-08",
118		"lesson-09",
119		"lesson-10",
120		"lesson-11",
121		// Task 4.3's final band — the three lessons that replaced the last
122		// fourteen video slots — and the optional numerals track.
123		"lesson-12",
124		"lesson-13",
125		"lesson-14",
126		"lesson-numerals",
127		// Phase 3's three promoted lessons.
128		"lesson-unwritten-vowels",
129		"lesson-clusters",
130		"lesson-leading-consonants",
131		// Task 4.2 — the consolidated tone-mark lesson.
132		"lesson-tone-marks",
133	]);
134	
135	export type LessonContentResolution =
136		/** Declared, and its content source is known. */
137		| { readonly status: "resolved"; readonly content: LessonContent }
138		/** Declared, but no content source can be produced — with the reason. */
139		| { readonly status: "unresolvable"; readonly reason: string }
140		/** No lesson with this id is declared at all. */
141		| { readonly status: "undeclared" };
142	
143	/**
144	 * The three statuses are distinct values on purpose: a lesson whose deck is
145	 * missing must never be indistinguishable from a lesson that does not exist,
146	 * because the first is a broken build and the second is an ordinary 404.
147	 */
148	export const LESSON_CONTENT_STATUSES = [
149		"resolved",
150		"unresolvable",
151		"undeclared",
152	] as const;
153	
154	/**
155	 * Content for a lesson that is known to be declared, so the only two outcomes
156	 * left are "resolved" and "unresolvable". Split out from `resolveLessonContent`
157	 * because the undeclared case is decided by the lookup and this one is not —
158	 * a declared lesson with no deck must never read as a lesson that does not
159	 * exist.
160	 */
161	export function lessonContentFor(
162		entry: LessonSequenceEntry,
163	): LessonContentResolution {
164		if (!DECK_LESSON_IDS.has(entry.id)) {
165			return {
166				status: "unresolvable",
167				reason: "lessonId: declared in the sequence but has no deck",
168			};
169		}
170		const path = deckPathForLesson(entry.id);
171		if (!path.ok) return { status: "unresolvable", reason: path.error };
172		return {
173			status: "resolved",
174			content: { kind: "deck", deckPath: path.path },
175		};
176	}
177	
178	export function resolveLessonContent(value: unknown): LessonContentResolution {
179		const lookup = lessonEntryById(value);
180		if (!lookup.ok) return { status: "undeclared" };
181		return lessonContentFor(lookup.entry);
182	}
183	
184	// ============================================================================
185	// The rules block
186	// ============================================================================
187	
188	/**
189	 * A rule a lesson teaches, resolved from the tables that already declare it
190	 * (`toneRules`, `specialRules`) via the ids the lessons table already lists.
191	 * Rule slides render from this — they carry no prose of their own, so the
192	 * slide and the rule cannot drift apart.
193	 */
194	export interface LessonRule {
195		readonly id: string;
196		readonly kind: "tone" | "special";
197		readonly title: string;
198		readonly text: string;
199	}
200	
201	export function lessonRules(legacyNumber: number): readonly LessonRule[] {
202		const lesson = lessons.find((candidate) => candidate.number === legacyNumber);
203		if (!lesson) return [];
204	
205		const tone = lesson.toneRulesIntroduced.flatMap<LessonRule>((id) => {
206			const rule = toneRules.find((candidate) => candidate.id === id);
207			if (!rule) return [];
208			return [
209				{
210					id: rule.id,
211					kind: "tone",
212					title: `${rule.consonantClass} class + ${rule.syllableType} syllable = ${rule.resultingTone} tone`,
213					text: rule.description,
214				},
215			];
216		});
217		const special = lesson.specialRulesIntroduced.flatMap<LessonRule>((id) => {
218			const rule = specialRules.find((candidate) => candidate.id === id);
219			if (!rule) return [];
220			return [
221				{
222					id: rule.id,
223					kind: "special",
224					title: rule.title,
225					text: rule.description,
226				},
227			];
228		});
229		return [...tone, ...special];
230	}
231	
232	// ============================================================================
233	// The deck schema
234	// ============================================================================
235	
236	export interface DeckExpositionSlide {
237		readonly kind: "exposition";
238		readonly id: string;
239		readonly heading: string;
240		readonly body: readonly string[];
241	}
242	
243	/**
244	 * A prompt the learner attempts. It names the reveal that answers it and
245	 * carries no answer itself — the attempt is the mechanism, so an answer
246	 * sitting on the same slide defeats the slide entirely.
247	 */
248	export interface DeckRetrievalSlide {
249		readonly kind: "retrieval";
250		readonly id: string;
251		readonly prompt: string;
252		readonly revealSlideId: string;
253	}
254	
255	export interface DeckRevealSlide {
256		readonly kind: "reveal";
257		readonly id: string;
258		readonly retrievalSlideId: string;
259		readonly answers: readonly string[];
260	}
261	
262	/** Renders from the lesson's rules block; holds no prose of its own. */
263	export interface DeckRuleSlide {
264		readonly kind: "rule";
265		readonly id: string;
266		readonly ruleId: string;
267	}
268	
269	export type DeckSlide =
270		| DeckExpositionSlide
271		| DeckRetrievalSlide
272		| DeckRevealSlide
273		| DeckRuleSlide;
274	
275	export interface LessonDeck {
276		readonly lessonId: string;
277		readonly title: string;
278		readonly slides: readonly DeckSlide[];
279	}
280	
281	export type DeckErrorCode =
282		| "malformed"
283		| "lesson-id-refused"
284		| "duplicate-slide-id"
285		| "retrieval-answer-on-same-slide"
286		| "dangling-reveal"
287		| "reveal-before-retrieval"
288		| "missing-retrieval"
289		| "unknown-rule"
290		| "rule-slide-carries-prose";
291	
292	export interface DeckValidationError {
293		readonly code: DeckErrorCode;
294		readonly message: string;
295		readonly slideId?: string;
296	}
297	
298	export type DeckValidationResult =
299		| { readonly ok: true; readonly deck: LessonDeck }
300		| { readonly ok: false; readonly errors: readonly DeckValidationError[] };
301	
302	/** Keys that would put an answer on the retrieval slide itself. */
303	const ANSWER_KEYS = ["answer", "answers", "reveal", "solution"] as const;
304	/** Keys that would let a rule slide state a rule differently from the block. */
305	const PROSE_KEYS = ["heading", "body", "text", "description"] as const;
306	
307	function isRecord(value: unknown): value is Record<string, unknown> {
308		return typeof value === "object" && value !== null && !Array.isArray(value);
309	}
310	
311	function isStringArray(value: unknown): value is string[] {
312		return (
313			Array.isArray(value) && value.every((item) => typeof item === "string")
314		);
315	}
316	
317	function parseSlide(
318		raw: unknown,
319		index: number,
320		errors: DeckValidationError[],
321	): DeckSlide | undefined {
322		const at = `slides[${index}]`;
323		if (!isRecord(raw)) {
324			errors.push({ code: "malformed", message: `${at}: not an object` });
325			return undefined;
326		}
327		const id = raw.id;
328		if (typeof id !== "string" || id.length === 0) {
329			errors.push({ code: "malformed", message: `${at}: missing a string id` });
330			return undefined;
331		}
332	
333		switch (raw.kind) {
334			case "exposition": {
335				if (typeof raw.heading !== "string" || !isStringArray(raw.body)) {
336					errors.push({
337						code: "malformed",
338						slideId: id,
339						message: `${at}: an exposition slide needs a heading and a body of strings`,
340					});
341					return undefined;
342				}
343				return { kind: "exposition", id, heading: raw.heading, body: raw.body };
344			}
345			case "retrieval": {
346				if (
347					typeof raw.prompt !== "string" ||
348					typeof raw.revealSlideId !== "string"
349				) {
350					errors.push({
351						code: "malformed",
352						slideId: id,
353						message: `${at}: a retrieval slide needs a prompt and a revealSlideId`,
354					});
355					return undefined;
356				}
357				const leaked = ANSWER_KEYS.find((key) => key in raw);
358				if (leaked) {
359					errors.push({
360						code: "retrieval-answer-on-same-slide",
361						slideId: id,
362						message: `${at}: retrieval slide carries "${leaked}"; the answer must live on the reveal slide it names, not beside the prompt`,
363					});
364					return undefined;
365				}
366				return {
367					kind: "retrieval",
368					id,
369					prompt: raw.prompt,
370					revealSlideId: raw.revealSlideId,
371				};
372			}
373			case "reveal": {
374				if (
375					typeof raw.retrievalSlideId !== "string" ||
376					!isStringArray(raw.answers)
377				) {
378					errors.push({
379						code: "malformed",
380						slideId: id,
381						message: `${at}: a reveal slide needs a retrievalSlideId and answers`,
382					});
383					return undefined;
384				}
385				return {
386					kind: "reveal",
387					id,
388					retrievalSlideId: raw.retrievalSlideId,
389					answers: raw.answers,
390				};
391			}
392			case "rule": {
393				if (typeof raw.ruleId !== "string") {
394					errors.push({
395						code: "malformed",
396						slideId: id,
397						message: `${at}: a rule slide needs a ruleId`,
398					});
399					return undefined;
400				}
401				const prose = PROSE_KEYS.find((key) => key in raw);
402				if (prose) {
403					errors.push({
404						code: "rule-slide-carries-prose",
405						slideId: id,
406						message: `${at}: rule slide carries "${prose}"; a rule slide renders from the lesson's rules block so the two cannot disagree`,
407					});
408					return undefined;
409				}
410				return { kind: "rule", id, ruleId: raw.ruleId };
411			}
412			default:
413				errors.push({
414					code: "malformed",
415					slideId: id,
416					message: `${at}: unknown slide kind`,
417				});
418				return undefined;
419		}
420	}
421	
422	function checkRetrieval(
423		slides: readonly DeckSlide[],
424		errors: DeckValidationError[],
425	): void {
426		const retrievalsSeen = new Set<string>();
427		let pairs = 0;
428	
429		for (const slide of slides) {
430			if (slide.kind === "retrieval") {
431				retrievalsSeen.add(slide.id);
432				continue;
433			}
434			if (slide.kind !== "reveal") continue;
435	
436			const target = slides.find(
437				(candidate) =>
438					candidate.kind === "retrieval" &&
439					candidate.id === slide.retrievalSlideId,
440			);
441			if (!target) {
442				errors.push({
443					code: "dangling-reveal",
444					slideId: slide.id,
445					message: `reveal "${slide.id}" names no retrieval slide that exists`,
446				});
447				continue;
448			}
449			if (!retrievalsSeen.has(slide.retrievalSlideId)) {
450				errors.push({
451					code: "reveal-before-retrieval",
452					slideId: slide.id,
453					message: `reveal "${slide.id}" comes before the retrieval step it answers; the learner must attempt first`,
454				});
455				continue;
456			}
457			pairs += 1;
458		}
459	
460		if (pairs === 0) {
461			errors.push({
462				code: "missing-retrieval",
463				message:
464					"deck has no retrieval step before a reveal: a deck must ask the learner to attempt at least one answer before showing it",
465			});
466		}
467	}
468	
469	export function validateDeck(value: unknown): DeckValidationResult {
470		const errors: DeckValidationError[] = [];
471	
472		if (!isRecord(value)) {
473			return {
474				ok: false,
475				errors: [{ code: "malformed", message: "deck: not an object" }],
476			};
477		}
478		const lessonId = parseLessonId(value.lessonId, "lessonId");
479		if (!lessonId.ok) {
480			return {
481				ok: false,
482				errors: [{ code: "lesson-id-refused", message: lessonId.error }],
483			};
484		}
485		if (typeof value.title !== "string" || value.title.length === 0) {
486			errors.push({ code: "malformed", message: "deck: missing a title" });
487		}
488		if (!Array.isArray(value.slides)) {
489			return {
490				ok: false,
491				errors: [
492					...errors,
493					{ code: "malformed", message: "deck: slides must be an array" },
494				],
495			};
496		}
497	
498		const slides: DeckSlide[] = [];
499		const seenIds = new Set<string>();
500		value.slides.forEach((raw, index) => {
501			const slide = parseSlide(raw, index, errors);
502			if (!slide) return;
503			if (seenIds.has(slide.id)) {
504				errors.push({
505					code: "duplicate-slide-id",
506					slideId: slide.id,
507					message: `slides[${index}]: slide id is already used`,
508				});
509				return;
510			}
511			seenIds.add(slide.id);
512			slides.push(slide);
513		});
514	
515		checkRetrieval(slides, errors);
516	
517		const entry = lessonEntryById(lessonId.id);
518		const rules = entry.ok ? lessonRules(entry.entry.legacyNumber) : [];
519		for (const slide of slides) {
520			if (slide.kind !== "rule") continue;
521			if (!rules.some((rule) => rule.id === slide.ruleId)) {
522				errors.push({
523					code: "unknown-rule",
524					slideId: slide.id,
525					message: `rule slide "${slide.id}" names a rule this lesson does not declare`,
526				});
527			}
528		}
529	
530		if (errors.length > 0) return { ok: false, errors };
531		return {
532			ok: true,
533			deck: { lessonId: lessonId.id, title: value.title as string, slides },
534		};
535	}
536	
537	/**
538	 * The rendering source for a rule slide: the lesson's own rules-block entry.
539	 * There is no other text on the slide, which is what makes "the lesson applies
540	 * the rule as it states it" checkable at all.
541	 */
542	export function renderRuleSlide(
543		deck: LessonDeck,
544		slide: DeckRuleSlide,
545	): LessonRule | undefined {
546		const entry = lessonEntryById(deck.lessonId);
547		if (!entry.ok) return undefined;
548		return lessonRules(entry.entry.legacyNumber).find(
549			(rule) => rule.id === slide.ruleId,
550		);
551	}
