/**
 * What a lesson *serves* — and the schema the in-house decks are written to.
 *
 * The content-source seam: `LessonContent` names its one arm with a `kind`
 * discriminant, dispatched exhaustively with a `never` default, so the
 * compiler refuses a dispatch that forgets a case. Task 6.2 deleted the
 * licensed-`.webm` arm and the 25 files it served; a lesson serves only an
 * in-house deck now.
 *
 * The deck schema's one non-structural demand is **retrieval**: a deck is
 * invalid unless the learner is asked to attempt something before the answer
 * is shown. A guideline would be honoured by the first deck and forgotten by
 * the twelfth; a schema rule is checked on every deck for free.
 */

import {
	type LessonSequenceEntry,
	lessonEntryById,
	parseLessonId,
} from "./lessonSequence";
import { lessons, specialRules, toneRules } from "./symbols";

// ============================================================================
// The content union
// ============================================================================

/**
 * The strangler is closed (task 6.2): the licensed video arm is gone, and a
 * lesson's content is always a deck. This is a plain object type now, not a
 * `|` of variants — but the `kind` discriminant and the `never` default in
 * `describeLessonContent` stay, because they're what makes the next content
 * source a compile error here rather than a silent fallthrough, exactly as
 * they did when this had two arms.
 */
export type LessonContent = {
	readonly kind: "deck";
	readonly deckPath: string;
};

/**
 * Exhaustive dispatch over `LessonContent`. The `never` default is the point:
 * adding a second arm without handling it here is a compile error, which is
 * how every downstream dispatch is kept honest too.
 */
export function describeLessonContent(content: LessonContent): string {
	switch (content.kind) {
		case "deck":
			return `deck ${content.deckPath}`;
		default: {
			// Narrows on `content.kind`, not `content` itself: with a single
			// literal-object type (no `|`) rather than a union of variants,
			// TypeScript only narrows the switched-on property to `never`
			// here, not the whole object — so that's what a future arm's
			// compile error has to hinge on.
			const _never: never = content.kind;
			return _never;
		}
	}
}

// ============================================================================
// Asset paths
// ============================================================================

/**
 * Public root under which every generated lesson asset lives. Includes the
 * app's deploy base path (`vite.config.ts`'s `base: "/thai-script/"`) —
 * every other asset URL in this codebase (`symbols.ts`'s `audioUrl` fields)
 * is hardcoded the same way, and a root that omits it 404s once the app is
 * actually served under that base, dev included.
 */
export const LESSON_ASSET_ROOT = "/thai-script/lessons";

export type DeckPathResult =
	| { readonly ok: true; readonly path: string }
	| { readonly ok: false; readonly error: string };

/**
 * The one place a filesystem/URL path is derived from a lesson id, and so the
 * one place the charset has to hold. Task 1.3 owns the containment check at
 * the generator's write boundary; this owns the charset.
 */
export function deckPathForLesson(
	value: unknown,
	key = "lessonId",
): DeckPathResult {
	const parsed = parseLessonId(value, key);
	if (!parsed.ok) return parsed;
	return { ok: true, path: `${LESSON_ASSET_ROOT}/${parsed.id}/deck.json` };
}

// ============================================================================
// Resolution — three states, and "unresolvable" never reads as "undeclared"
// ============================================================================

/**
 * Lessons whose content is an in-house deck. The strangler grew this set one
 * band at a time from task 1.4's `lesson-01`; task 4.3 closed it — every
 * declared lesson is here, and no lesson resolves to the video arm any more.
 *
 * `lesson-sound-buckets` is deliberately absent: it has no `legacyNumber` in
 * `lessonSequence.ts`, and giving it one is a lesson-identity decision
 * (CONTEXT.md Rule 1 — the five-store hazard) that belongs with the task
 * that owns that migration, not a one-line addition here. Its deck is
 * committed and schema-valid (see `openingBand.test.ts`) but unreachable
 * from any route until that sequencing decision is made.
 */
export const DECK_LESSON_IDS: ReadonlySet<string> = new Set<string>([
	"lesson-01",
	"lesson-02",
	"lesson-03",
	"lesson-04",
	"lesson-05",
	// Phase 3's middle band.
	"lesson-06",
	"lesson-07",
	"lesson-08",
	"lesson-09",
	"lesson-10",
	"lesson-11",
	// Task 4.3's final band — the three lessons that replaced the last
	// fourteen video slots — and the optional numerals track.
	"lesson-12",
	"lesson-13",
	"lesson-14",
	"lesson-numerals",
	// Phase 3's three promoted lessons.
	"lesson-unwritten-vowels",
	"lesson-clusters",
	"lesson-leading-consonants",
	// Task 4.2 — the consolidated tone-mark lesson.
	"lesson-tone-marks",
]);

export type LessonContentResolution =
	/** Declared, and its content source is known. */
	| { readonly status: "resolved"; readonly content: LessonContent }
	/** Declared, but no content source can be produced — with the reason. */
	| { readonly status: "unresolvable"; readonly reason: string }
	/** No lesson with this id is declared at all. */
	| { readonly status: "undeclared" };

/**
 * The three statuses are distinct values on purpose: a lesson whose deck is
 * missing must never be indistinguishable from a lesson that does not exist,
 * because the first is a broken build and the second is an ordinary 404.
 */
export const LESSON_CONTENT_STATUSES = [
	"resolved",
	"unresolvable",
	"undeclared",
] as const;

/**
 * Content for a lesson that is known to be declared, so the only two outcomes
 * left are "resolved" and "unresolvable". Split out from `resolveLessonContent`
 * because the undeclared case is decided by the lookup and this one is not —
 * a declared lesson with no deck must never read as a lesson that does not
 * exist.
 */
export function lessonContentFor(
	entry: LessonSequenceEntry,
): LessonContentResolution {
	if (!DECK_LESSON_IDS.has(entry.id)) {
		return {
			status: "unresolvable",
			reason: "lessonId: declared in the sequence but has no deck",
		};
	}
	const path = deckPathForLesson(entry.id);
	if (!path.ok) return { status: "unresolvable", reason: path.error };
	return {
		status: "resolved",
		content: { kind: "deck", deckPath: path.path },
	};
}

export function resolveLessonContent(value: unknown): LessonContentResolution {
	const lookup = lessonEntryById(value);
	if (!lookup.ok) return { status: "undeclared" };
	return lessonContentFor(lookup.entry);
}

// ============================================================================
// The rules block
// ============================================================================

/**
 * A rule a lesson teaches, resolved from the tables that already declare it
 * (`toneRules`, `specialRules`) via the ids the lessons table already lists.
 * Rule slides render from this — they carry no prose of their own, so the
 * slide and the rule cannot drift apart.
 */
export interface LessonRule {
	readonly id: string;
	readonly kind: "tone" | "special";
	readonly title: string;
	readonly text: string;
}

export function lessonRules(legacyNumber: number): readonly LessonRule[] {
	const lesson = lessons.find((candidate) => candidate.number === legacyNumber);
	if (!lesson) return [];

	const tone = lesson.toneRulesIntroduced.flatMap<LessonRule>((id) => {
		const rule = toneRules.find((candidate) => candidate.id === id);
		if (!rule) return [];
		return [
			{
				id: rule.id,
				kind: "tone",
				title: `${rule.consonantClass} class + ${rule.syllableType} syllable = ${rule.resultingTone} tone`,
				text: rule.description,
			},
		];
	});
	const special = lesson.specialRulesIntroduced.flatMap<LessonRule>((id) => {
		const rule = specialRules.find((candidate) => candidate.id === id);
		if (!rule) return [];
		return [
			{
				id: rule.id,
				kind: "special",
				title: rule.title,
				text: rule.description,
			},
		];
	});
	return [...tone, ...special];
}

// ============================================================================
// The deck schema
// ============================================================================

export interface DeckExpositionSlide {
	readonly kind: "exposition";
	readonly id: string;
	readonly heading: string;
	readonly body: readonly string[];
}

/**
 * A prompt the learner attempts. It names the reveal that answers it and
 * carries no answer itself — the attempt is the mechanism, so an answer
 * sitting on the same slide defeats the slide entirely.
 */
export interface DeckRetrievalSlide {
	readonly kind: "retrieval";
	readonly id: string;
	readonly prompt: string;
	readonly revealSlideId: string;
}

export interface DeckRevealSlide {
	readonly kind: "reveal";
	readonly id: string;
	readonly retrievalSlideId: string;
	readonly answers: readonly string[];
}

/** Renders from the lesson's rules block; holds no prose of its own. */
export interface DeckRuleSlide {
	readonly kind: "rule";
	readonly id: string;
	readonly ruleId: string;
}

export type DeckSlide =
	| DeckExpositionSlide
	| DeckRetrievalSlide
	| DeckRevealSlide
	| DeckRuleSlide;

export interface LessonDeck {
	readonly lessonId: string;
	readonly title: string;
	readonly slides: readonly DeckSlide[];
}

export type DeckErrorCode =
	| "malformed"
	| "lesson-id-refused"
	| "duplicate-slide-id"
	| "retrieval-answer-on-same-slide"
	| "dangling-reveal"
	| "reveal-before-retrieval"
	| "missing-retrieval"
	| "unknown-rule"
	| "rule-slide-carries-prose";

export interface DeckValidationError {
	readonly code: DeckErrorCode;
	readonly message: string;
	readonly slideId?: string;
}

export type DeckValidationResult =
	| { readonly ok: true; readonly deck: LessonDeck }
	| { readonly ok: false; readonly errors: readonly DeckValidationError[] };

/** Keys that would put an answer on the retrieval slide itself. */
const ANSWER_KEYS = ["answer", "answers", "reveal", "solution"] as const;
/** Keys that would let a rule slide state a rule differently from the block. */
const PROSE_KEYS = ["heading", "body", "text", "description"] as const;

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
	return (
		Array.isArray(value) && value.every((item) => typeof item === "string")
	);
}

function parseSlide(
	raw: unknown,
	index: number,
	errors: DeckValidationError[],
): DeckSlide | undefined {
	const at = `slides[${index}]`;
	if (!isRecord(raw)) {
		errors.push({ code: "malformed", message: `${at}: not an object` });
		return undefined;
	}
	const id = raw.id;
	if (typeof id !== "string" || id.length === 0) {
		errors.push({ code: "malformed", message: `${at}: missing a string id` });
		return undefined;
	}

	switch (raw.kind) {
		case "exposition": {
			if (typeof raw.heading !== "string" || !isStringArray(raw.body)) {
				errors.push({
					code: "malformed",
					slideId: id,
					message: `${at}: an exposition slide needs a heading and a body of strings`,
				});
				return undefined;
			}
			return { kind: "exposition", id, heading: raw.heading, body: raw.body };
		}
		case "retrieval": {
			if (
				typeof raw.prompt !== "string" ||
				typeof raw.revealSlideId !== "string"
			) {
				errors.push({
					code: "malformed",
					slideId: id,
					message: `${at}: a retrieval slide needs a prompt and a revealSlideId`,
				});
				return undefined;
			}
			const leaked = ANSWER_KEYS.find((key) => key in raw);
			if (leaked) {
				errors.push({
					code: "retrieval-answer-on-same-slide",
					slideId: id,
					message: `${at}: retrieval slide carries "${leaked}"; the answer must live on the reveal slide it names, not beside the prompt`,
				});
				return undefined;
			}
			return {
				kind: "retrieval",
				id,
				prompt: raw.prompt,
				revealSlideId: raw.revealSlideId,
			};
		}
		case "reveal": {
			if (
				typeof raw.retrievalSlideId !== "string" ||
				!isStringArray(raw.answers)
			) {
				errors.push({
					code: "malformed",
					slideId: id,
					message: `${at}: a reveal slide needs a retrievalSlideId and answers`,
				});
				return undefined;
			}
			return {
				kind: "reveal",
				id,
				retrievalSlideId: raw.retrievalSlideId,
				answers: raw.answers,
			};
		}
		case "rule": {
			if (typeof raw.ruleId !== "string") {
				errors.push({
					code: "malformed",
					slideId: id,
					message: `${at}: a rule slide needs a ruleId`,
				});
				return undefined;
			}
			const prose = PROSE_KEYS.find((key) => key in raw);
			if (prose) {
				errors.push({
					code: "rule-slide-carries-prose",
					slideId: id,
					message: `${at}: rule slide carries "${prose}"; a rule slide renders from the lesson's rules block so the two cannot disagree`,
				});
				return undefined;
			}
			return { kind: "rule", id, ruleId: raw.ruleId };
		}
		default:
			errors.push({
				code: "malformed",
				slideId: id,
				message: `${at}: unknown slide kind`,
			});
			return undefined;
	}
}

function checkRetrieval(
	slides: readonly DeckSlide[],
	errors: DeckValidationError[],
): void {
	const retrievalsSeen = new Set<string>();
	let pairs = 0;

	for (const slide of slides) {
		if (slide.kind === "retrieval") {
			retrievalsSeen.add(slide.id);
			continue;
		}
		if (slide.kind !== "reveal") continue;

		const target = slides.find(
			(candidate) =>
				candidate.kind === "retrieval" &&
				candidate.id === slide.retrievalSlideId,
		);
		if (!target) {
			errors.push({
				code: "dangling-reveal",
				slideId: slide.id,
				message: `reveal "${slide.id}" names no retrieval slide that exists`,
			});
			continue;
		}
		if (!retrievalsSeen.has(slide.retrievalSlideId)) {
			errors.push({
				code: "reveal-before-retrieval",
				slideId: slide.id,
				message: `reveal "${slide.id}" comes before the retrieval step it answers; the learner must attempt first`,
			});
			continue;
		}
		pairs += 1;
	}

	if (pairs === 0) {
		errors.push({
			code: "missing-retrieval",
			message:
				"deck has no retrieval step before a reveal: a deck must ask the learner to attempt at least one answer before showing it",
		});
	}
}

export function validateDeck(value: unknown): DeckValidationResult {
	const errors: DeckValidationError[] = [];

	if (!isRecord(value)) {
		return {
			ok: false,
			errors: [{ code: "malformed", message: "deck: not an object" }],
		};
	}
	const lessonId = parseLessonId(value.lessonId, "lessonId");
	if (!lessonId.ok) {
		return {
			ok: false,
			errors: [{ code: "lesson-id-refused", message: lessonId.error }],
		};
	}
	if (typeof value.title !== "string" || value.title.length === 0) {
		errors.push({ code: "malformed", message: "deck: missing a title" });
	}
	if (!Array.isArray(value.slides)) {
		return {
			ok: false,
			errors: [
				...errors,
				{ code: "malformed", message: "deck: slides must be an array" },
			],
		};
	}

	const slides: DeckSlide[] = [];
	const seenIds = new Set<string>();
	value.slides.forEach((raw, index) => {
		const slide = parseSlide(raw, index, errors);
		if (!slide) return;
		if (seenIds.has(slide.id)) {
			errors.push({
				code: "duplicate-slide-id",
				slideId: slide.id,
				message: `slides[${index}]: slide id is already used`,
			});
			return;
		}
		seenIds.add(slide.id);
		slides.push(slide);
	});

	checkRetrieval(slides, errors);

	const entry = lessonEntryById(lessonId.id);
	const rules = entry.ok ? lessonRules(entry.entry.legacyNumber) : [];
	for (const slide of slides) {
		if (slide.kind !== "rule") continue;
		if (!rules.some((rule) => rule.id === slide.ruleId)) {
			errors.push({
				code: "unknown-rule",
				slideId: slide.id,
				message: `rule slide "${slide.id}" names a rule this lesson does not declare`,
			});
		}
	}

	if (errors.length > 0) return { ok: false, errors };
	return {
		ok: true,
		deck: { lessonId: lessonId.id, title: value.title as string, slides },
	};
}

/**
 * The rendering source for a rule slide: the lesson's own rules-block entry.
 * There is no other text on the slide, which is what makes "the lesson applies
 * the rule as it states it" checkable at all.
 */
export function renderRuleSlide(
	deck: LessonDeck,
	slide: DeckRuleSlide,
): LessonRule | undefined {
	const entry = lessonEntryById(deck.lessonId);
	if (!entry.ok) return undefined;
	return lessonRules(entry.entry.legacyNumber).find(
		(rule) => rule.id === slide.ruleId,
	);
}

/**
 * The declared lesson sequence: the one place lesson identity and lesson
 * ordering are written down.
 *
 * A lesson is identified by a stable `id`, ordered by array position, and
 * joined to the `symbols.ts` tables through `legacyNumber` — the integer the
 * five persisted stores keyed on before task 1.1b's migration, and the value
 * `sym.lesson` still carries. Persisted stores hold *positions*; every join
 * against the legacy space routes through this table.
 *
 * Task 4.3 closed the sequence: the fourteen video lessons that remained
 * (legacy 12-25) are replaced by three in-house lessons (12-14) and the
 * retired numbers below, the three promoted lessons and the consolidated
 * tone-mark lesson take their teaching positions, and Thai numerals become an
 * optional track at the end. Ordering is read from `lessonSequence` and from
 * nowhere else; the lesson *counts* are derived from it, never written as
 * literals.
 */

/**
 * Lesson ids double as a path segment under `public/lessons/` and as a lookup
 * key, so the charset is closed rather than merely conventional.
 */
export const LESSON_ID_PATTERN = /^[a-z0-9-]{1,64}$/;

export interface LessonSequenceEntry {
	/** Stable identity. Survives resequencing; never reused for another lesson. */
	readonly id: string;
	/** 1-based place in the course. Derived from declaration order. */
	readonly position: number;
	/**
	 * The integer `symbols.ts` files this lesson's rows and symbols under
	 * (CONTEXT.md Rule 1). Unique forever: a retired number is never reused,
	 * because persisted cards written under the old numbering still carry it.
	 */
	readonly legacyNumber: number;
	/**
	 * Whether completing this lesson is part of completing the course.
	 * `false` marks an optional track — taught, reachable, but a learner who
	 * declines it has not left the course incomplete (task 4.3 AC4).
	 */
	readonly required: boolean;
}

/**
 * Declaration order is the course order. Positions are assigned from it.
 *
 * The ordering constraints this declaration satisfies, in one place so a
 * resequence can check itself against them:
 * - lessons 12-14 teach every consonant and written vowel not taught by the
 *   opening and middle bands, so everything after them may use any symbol;
 * - `lesson-tone-marks` comes after every spelling-based tone rule
 *   (`toneRules`, lessons 2-13) and before `lesson-clusters` and
 *   `lesson-leading-consonants`, whose decks print marked words;
 * - `lesson-unwritten-vowels` comes after lesson-14, whose letters (ฎ, ฏ)
 *   appear in its examples;
 * - `lesson-numerals` is last: `startLesson` requires every earlier position
 *   complete, so an optional track anywhere else would block the course.
 */
const DECLARED: readonly Omit<LessonSequenceEntry, "position">[] = [
	{ id: "lesson-01", legacyNumber: 1, required: true },
	{ id: "lesson-02", legacyNumber: 2, required: true },
	{ id: "lesson-03", legacyNumber: 3, required: true },
	{ id: "lesson-04", legacyNumber: 4, required: true },
	{ id: "lesson-05", legacyNumber: 5, required: true },
	{ id: "lesson-06", legacyNumber: 6, required: true },
	{ id: "lesson-07", legacyNumber: 7, required: true },
	{ id: "lesson-08", legacyNumber: 8, required: true },
	{ id: "lesson-09", legacyNumber: 9, required: true },
	{ id: "lesson-10", legacyNumber: 10, required: true },
	{ id: "lesson-11", legacyNumber: 11, required: true },
	{ id: "lesson-12", legacyNumber: 12, required: true },
	{ id: "lesson-13", legacyNumber: 13, required: true },
	{ id: "lesson-14", legacyNumber: 14, required: true },
	{ id: "lesson-unwritten-vowels", legacyNumber: 26, required: true },
	{ id: "lesson-tone-marks", legacyNumber: 29, required: true },
	{ id: "lesson-clusters", legacyNumber: 27, required: true },
	{ id: "lesson-leading-consonants", legacyNumber: 28, required: true },
	{ id: "lesson-numerals", legacyNumber: 30, required: false },
];

export const lessonSequence: readonly LessonSequenceEntry[] = Object.freeze(
	DECLARED.map((entry, index) =>
		Object.freeze({ ...entry, position: index + 1 }),
	),
);

/**
 * The legacy numbers this resequence retired, each mapped to the lesson that
 * absorbed the bulk of its material. Persisted stores written under the old
 * numbering still carry these values, and `migrateLessonIdentity`
 * (`Storage.ts`) currently *refuses* a state that references an undeclared
 * number — the epoch-marked migration its own NOTE calls for must consume
 * this map before the resequence reaches a learner's browser. Declared here
 * so that migration reads the mapping off the resequence that caused it.
 */
export const RETIRED_LESSONS: readonly {
	readonly legacyNumber: number;
	readonly absorbedBy: string;
}[] = Object.freeze([
	{ legacyNumber: 15, absorbedBy: "lesson-12" }, // ห; -ัว/-ัวะ moved to lesson-14
	{ legacyNumber: 16, absorbedBy: "lesson-13" }, // ภ ธ ณ ญ, ำ
	{ legacyNumber: 17, absorbedBy: "lesson-tone-marks" }, // ่ ้
	{ legacyNumber: 18, absorbedBy: "lesson-tone-marks" }, // ๊ ๋
	{ legacyNumber: 19, absorbedBy: "lesson-14" }, // ถ moved to lesson-12; ฐ ฎ ฏ
	{ legacyNumber: 20, absorbedBy: "lesson-14" }, // ฑ ฒ
	{ legacyNumber: 21, absorbedBy: "lesson-14" }, // ฬ ฆ
	{ legacyNumber: 22, absorbedBy: "lesson-14" }, // ฃ ฅ ฌ, ฤ ฤๅ ฦ ฦๅ
	{ legacyNumber: 23, absorbedBy: "lesson-numerals" }, // ๑ ๒ ๓
	{ legacyNumber: 24, absorbedBy: "lesson-numerals" }, // ๔ ๕ ๖
	{ legacyNumber: 25, absorbedBy: "lesson-numerals" }, // ๗ ๘ ๙ ๐
]);

/**
 * The number of lessons a learner must complete for the course to be
 * complete — the required lessons, not the declared entries. The completion
 * consumers (`AchievementService`'s `completedLessons.length >= lessonCount`
 * and the badge copy built from the same value) read this, which is what
 * keeps an optional track from silently holding the course open (AC4).
 * Navigation walks `lessonSequence` itself and shows every entry.
 */
export const lessonCount = lessonSequence.filter(
	(entry) => entry.required,
).length;

// ============================================================================
// The numerals track (AC4)
// ============================================================================

/**
 * The three states the optional numerals track can be in for a learner, as
 * three distinct values. "skipped" is a first-class state, not an absence:
 * the learner finished every required lesson and the course closed without
 * the track, which is a different fact from not having reached it yet.
 */
export type NumeralsTrackState = "not-started" | "completed" | "skipped";

/**
 * Resolves the numerals track's state from the learner's completed positions.
 *
 * - "completed": the numerals lesson itself was completed.
 * - "skipped": every required lesson is complete and the numerals lesson is
 *   not — the learner reached the end of the course and moved past the track.
 *   Starting the track later flips this to "completed"; nothing is lost.
 * - "not-started": the course is still in progress and the track has not
 *   been reached.
 */
export function numeralsTrackState(
	completedLessons: readonly number[],
): NumeralsTrackState {
	const completed = new Set(completedLessons);
	const numerals = lessonSequence.find((entry) => !entry.required);
	if (!numerals) return "not-started";
	if (completed.has(numerals.position)) return "completed";
	const requiredDone = lessonSequence.every(
		(entry) => !entry.required || completed.has(entry.position),
	);
	return requiredDone ? "skipped" : "not-started";
}

export type LessonIdRefusal = { readonly ok: false; readonly error: string };

export type LessonIdResult =
	| { readonly ok: true; readonly id: string }
	| LessonIdRefusal;

/**
 * The gate every path derivation and every lookup passes an id through.
 *
 * The refusal names `key` and deliberately does **not** echo the value: a
 * rejected id is by definition attacker-shaped (`../../etc/passwd`), and the
 * message ends up in logs and findings.
 */
export function parseLessonId(
	value: unknown,
	key = "lessonId",
): LessonIdResult {
	if (typeof value !== "string") {
		return { ok: false, error: `${key}: expected a string lesson id` };
	}
	if (!LESSON_ID_PATTERN.test(value)) {
		return {
			ok: false,
			error: `${key}: not a lesson id (must match ${LESSON_ID_PATTERN.source})`,
		};
	}
	return { ok: true, id: value };
}

export type LessonLookupResult =
	| { readonly ok: true; readonly entry: LessonSequenceEntry }
	| LessonIdRefusal;

/** Lookup by stable id. Refuses a malformed id rather than simply missing it. */
export function lessonEntryById(
	value: unknown,
	key = "lessonId",
): LessonLookupResult {
	const parsed = parseLessonId(value, key);
	if (!parsed.ok) return parsed;
	const entry = lessonSequence.find((candidate) => candidate.id === parsed.id);
	if (!entry) {
		return { ok: false, error: `${key}: no lesson is declared with this id` };
	}
	return { ok: true, entry };
}

/**
 * The lessons phase 3 produced, by stable id — the six middle-band lessons
 * and the three concepts promoted from asides.
 *
 * Declared here rather than in either content task because tasks 3.2 and 3.3
 * ran concurrently on disjoint files: if each placed its own lessons, neither
 * would see the other's ordering and the scheduler could not catch the
 * collision.
 */
export const PHASE_THREE_LESSON_IDS: readonly string[] = Object.freeze([
	"lesson-06",
	"lesson-07",
	"lesson-08",
	"lesson-09",
	"lesson-10",
	"lesson-11",
	"lesson-unwritten-vowels",
	"lesson-clusters",
	"lesson-leading-consonants",
]);

export interface SlotReconciliation {
	/** Declared in the sequence, with no content authored for it yet. */
	readonly unfilled: readonly string[];
	/** Content exists, but no slot in the sequence declares it. */
	readonly orphaned: readonly string[];
	/** Declared and filled — one lesson, one slot. */
	readonly filled: readonly string[];
}

/**
 * Slots and content, reconciled in both directions.
 *
 * Both halves are reported rather than asserted away: during a phase a slot
 * legitimately has no content yet, and a lesson that shipped content without a
 * slot (`lesson-sound-buckets` is one today) is unreachable from any route —
 * a defect that is invisible unless something counts it.
 */
export function reconcileLessonSlots(
	contentLessonIds: readonly string[],
): SlotReconciliation {
	const declared = new Set(lessonSequence.map((entry) => entry.id));
	const content = new Set(contentLessonIds);
	return {
		unfilled: lessonSequence
			.map((entry) => entry.id)
			.filter((id) => !content.has(id)),
		orphaned: [...content].filter((id) => !declared.has(id)).sort(),
		filled: lessonSequence
			.map((entry) => entry.id)
			.filter((id) => content.has(id)),
	};
}

/** Lookup by the integer the `symbols.ts` tables still use. */
export function lessonEntryByNumber(
	legacyNumber: number,
): LessonSequenceEntry | undefined {
	return lessonSequence.find((entry) => entry.legacyNumber === legacyNumber);
}

/**
 * Lookup by 1-based position — the space persisted state and routes live in.
 *
 * Distinct from {@link lessonEntryByNumber} on purpose: position and legacy
 * number were the same integer until task 4.3's resequence, so a caller
 * holding a position could reach for the legacy lookup and be silently
 * right. They now diverge from position 15 on, and the two lookups exist so
 * the call site names which space its integer is in.
 */
export function lessonEntryByPosition(
	position: number,
): LessonSequenceEntry | undefined {
	return lessonSequence[position - 1];
}

