278	export class LocalStorageAdapter implements IStorage {
279		private readonly key: string;
280	
281		/**
282		 * The parsed state, memoized against the exact raw string it came from.
283		 *
284		 * Without it every repository method re-ran `JSON.parse` + `migrateState`
285		 * over the whole learner state. Because pages call use cases directly
286		 * from their render bodies, one Dashboard render did that 42 times —
287		 * ~12 MB of JSON parsed for a single render, and ~5 MB more on every
288		 * answered card via the `Layout` shell's re-render. That was the app's
289		 * dominant CPU cost on a phone.
290		 *
