242	/**
243	 * The in-house deck experience: fetches `deckPath`, validates it against the
244	 * schema before anything renders (AC2), and steps through its slides in
245	 * declared order. Three states never collapse into one another: loading, an
246	 * empty deck, and a deck that failed to load or parse (AC3).
247	 *
248	 * Owns its own stepping — `onComplete` fires once, when the deck's own last
249	 * slide is confirmed forward, so the caller can hand off to whatever follows
250	 * (the lesson's symbol cards) using its own, separate navigation.
251	 */
252	export function DeckSlide({ deckPath, onComplete }: Props) {
253		const [state, setState] = useState<LoadState>({ status: "loading" });
254		const [idx, setIdx] = useState(0);
255	
256		useEffect(() => {
257			let cancelled = false;
258			setState({ status: "loading" });
259			setIdx(0);
260	
261			fetch(deckPath)
262				.then((res) => {
263					if (!res.ok) {
264						throw new Error(`request for ${deckPath} failed (${res.status})`);
265					}
266					return res.json();
267				})
268				.then((raw) => {
269					if (cancelled) return;
270					const result = validateDeck(raw);
271					if (!result.ok) {
272						// The schema's retrieval invariant (every deck must ask the
273						// learner to attempt something) is unconditional, so it also
274						// fires for a deck that authors nothing at all yet. That specific
275						// shape — structurally sound, zero slides, no other error — is
276						// the "empty deck" state AC3 asks to be distinguishable from a
277						// real validation failure, not an instance of one.
278						if (isUnauthoredEmptyDeck(raw, result.errors)) {
279							setState({
280								status: "ready",
281								deck: {
282									lessonId: (raw as Record<string, unknown>).lessonId as string,
283									title: (raw as Record<string, unknown>).title as string,
284									slides: [],
285								},
286								audioUrls: new Map(),
287							});
288							return;
289						}
290						setState({
291							status: "error",
292							message: result.errors.map((e) => e.message).join("; "),
293						});
294						return;
295					}
296					setState({
297						status: "ready",
298						deck: result.deck,
299						audioUrls: extractAudioUrls(raw, result.deck.lessonId),
300					});
301				})
302				.catch((err) => {
303					if (cancelled) return;
304					setState({
305						status: "error",
306						message: err instanceof Error ? err.message : "failed to load deck",
307					});
308				});
309	
310			return () => {
311				cancelled = true;
312			};
313		}, [deckPath]);
314	
315		const isReady = state.status === "ready";
316		const slides = isReady ? state.deck.slides : [];
317		const isLast = idx === slides.length - 1;
318	
319		const advance = useCallback(() => {
320			if (isLast) onComplete();
321			else setIdx((i) => i + 1);
322		}, [isLast, onComplete]);
323	
324		const goBack = useCallback(() => {
325			if (idx > 0) setIdx((i) => i - 1);
326		}, [idx]);
327	
328		if (state.status === "loading") {
329			return (
330				<p className="text-center" style={{ color: "var(--color-text-muted)" }}>
331					Loading lesson…
332				</p>
333			);
334		}
335	
336		if (state.status === "error") {
337			return (
338				<p role="alert" className="text-center">
339					Couldn't load this lesson: {state.message}
340				</p>
341			);
342		}
343	
344		if (slides.length === 0) {
345			return (
346				<p className="text-center" style={{ color: "var(--color-text-muted)" }}>
347					This lesson's deck has no slides yet.
348				</p>
349			);
350		}
351	
352		const slide = slides[idx];
353		if (!slide) return null;
354	
355		return (
356			<div className="space-y-6">
357				<DeckSlideContent
358					deck={state.deck}
359					slide={slide}
360					audioUrl={state.audioUrls.get(slide.id)}
361				/>
362				<div className="flex gap-3">
363					{idx > 0 && (
364						<Button
365							variant="secondary"
366							onClick={goBack}
367							className="px-6 py-3 h-auto rounded-xl"
368						>
369							Back
370						</Button>
371					)}
372					<Button onClick={advance} className="flex-1 py-3 h-auto rounded-xl">
373						{isLast ? "Continue" : "Next"}
374					</Button>
375				</div>
376			</div>
377		);
378	}
