1	/**
2	 * The originality gate: one check, consumed by every content task.
3	 *
4	 * The transcripts this course replaces are copyrighted. Facts about the Thai
5	 * writing system are free to reuse; the source's phrasing, its mnemonic images
6	 * and its curated examples are not, and the 82 mnemonic strings already in
7	 * `symbols.ts` are close paraphrases of exactly that material. Every task that
8	 * writes new prose has to be able to show that it did not paraphrase it again.
9	 *
10	 * The mechanism lives here and only here. The plan's first draft asserted an
11	 * overlap check in seven criteria spread across five tasks and produced it in
12	 * none of them, which would have meant the window width, the canary and the
13	 * size floor each being re-decided five times by five agents who could not see
14	 * each other. Content tasks import {@link checkOriginality} instead.
15	 *
16	 * ## What it compares against
17	 *
18	 * `originality-corpus.json`, built by `scripts/build-originality-corpus.py`
19	 * from both licensed PDF sets. That artifact holds **salted hashes and counts,
20	 * never text**: a gate that stored the extraction would be the largest
21	 * reproduction of the licensed material in the repository, which is precisely
22	 * the thing it exists to prevent. It is a membership oracle and nothing else.
23	 *
24	 * The normalisation and hashing below reproduce the Python side exactly. The
25	 * two are held together by the canary in `originality.test.ts`, which pushes a
26	 * phrase known to be verbatim in each PDF set through *this* code and requires
27	 * the *Python-built* artifact to contain it. Drift in tokenisation, Unicode
28	 * normalisation, the salt or the digest turns that test red.
29	 *
30	 * ## Why a canary rather than a planted overlap
31	 *
32	 * Planting a string in a fake corpus and finding it again proves the matching
33	 * algorithm runs. It says nothing about whether the real corpus was loaded,
34	 * and an empty corpus passes that test perfectly while clearing every
35	 * plagiarised candidate put to it. The canary is the check that the corpus is
36	 * *there*: a real phrase, from the real source, that must come back flagged.
37	 *
38	 * ## The third state
39	 *
40	 * A candidate is `cleared`, `overlapping`, or `not-checked`. The third exists
41	 * because the failure this gate is most likely to suffer is not a false clear
42	 * on a real paraphrase — it is the corpus silently failing to load and every
43	 * candidate sailing through. `not-checked` is a distinct value that no caller
44	 * can mistake for a pass, and {@link assertOriginal} throws on it.
45	 */
46	
47	import corpusArtifact from "./originality-corpus.json";
48	
49	/**
50	 * The comparison window, in tokens. **This is the single site.**
51	 *
52	 * Measured against the 82 shipped mnemonics — the only labelled positives that
53	 * exist, since CONTEXT.md establishes they are paraphrases of this source — an
54	 * 8-token window detects 17 and a 5-token window detects 48. The wider window
55	 * was chosen in the first draft because it sounded conservative; it is
56	 * near-vacuous. {@link loadOriginalityCorpus} refuses an artifact built at any
57	 * other width, so the constant cannot drift from the data it queries.
58	 */
59	export const NGRAM_WIDTH = 5;
60	
61	/**
62	 * Below this many source tokens the corpus is treated as unusable.
63	 *
64	 * The real corpus carries ~42,000. The floor is not a guess at "enough to be
65	 * useful" — it is far enough below the real figure to never fire spuriously
66	 * and far enough above zero to catch the failures that matter: an empty file,
67	 * a truncated write, a build that found one PDF instead of fifty.
68	 */
69	export const MINIMUM_CORPUS_TOKENS = 10_000;
70	
71	/** Which licensed set an n-gram came from. */
72	export type OriginalitySource =
73		| "lesson-notes"
74		| "recording-script"
75		| "worksheet";
76	
77	/**
78	 * The two sets the corpus may not be missing. The lesson notes are not
79	 * optional: the shipped ฌ mnemonic paraphrases a lesson-notes paragraph and
80	 * appears in no recording script, so a transcript-only corpus clears it.
81	 */
82	export const REQUIRED_CORPUS_SOURCES: readonly OriginalitySource[] = [
83		"lesson-notes",
84		"recording-script",
85	];
86	
87	/** Where a candidate collided with the source, and in which set. */
88	export interface OriginalityOverlap {
89		/** The candidate's own n-gram. Reporting it reproduces nothing committed. */
90		readonly ngram: string;
91		readonly sources: readonly OriginalitySource[];
92	}
93	
94	/**
95	 * A candidate is in exactly one of three states.
96	 *
97	 * Modelled as a discriminated union rather than a status plus optional fields
98	 * so that "not checked" cannot be read as "cleared" by a caller that forgot to
99	 * look: there is no branch of this type that carries a clearance without
100	 * saying so.
101	 */
102	export type OriginalityResult =
103		| { readonly status: "cleared"; readonly ngramsChecked: number }
104		| {
105				readonly status: "overlapping";
106				readonly ngramsChecked: number;
107				readonly overlap: OriginalityOverlap;
108		  }
109		| {
110				readonly status: "not-checked";
111				readonly ngramsChecked: 0;
112				readonly reason: string;
113		  };
114	
115	/** A corpus that loaded and passed its floor. */
116	export interface OriginalityCorpus {
117		readonly salt: string;
118		readonly ngramWidth: number;
119		readonly tokenCount: number;
120		/** Truncated salted digest to OR-ed source flags. */
121		readonly ngrams: Readonly<Record<string, number>>;
122		/** Source name to its bit in the flag values above. */
123		readonly sourceFlags: Readonly<Record<string, number>>;
124	}
125	
126	/** Why a corpus could not be used. Carries no clearance, by construction. */
127	export interface OriginalityCorpusFailure {
128		readonly reason: string;
129	}
130	
131	export type CorpusLoad = OriginalityCorpus | OriginalityCorpusFailure;
132	
133	export function isCorpusLoaded(load: CorpusLoad): load is OriginalityCorpus {
134		return !("reason" in load);
135	}
136	
137	/**
138	 * Characters that may appear inside a token: ASCII alphanumerics, Latin-1 and
139	 * Latin Extended-A/B plus combining diacritics (the romanisation writes "mǎa",
140	 * "thâo-rài"), and the whole Thai block including the vowel signs and tone
141	 * marks, which are combining characters.
142	 *
143	 * Spelled as explicit ranges rather than `\p{L}`/`\p{N}` because Python and
144	 * JavaScript do not agree on how those classify combining marks, and this
145	 * expression has to yield byte-identical tokens on both sides or every hash
146	 * disagrees. `TOKEN_PATTERN` in `build-originality-corpus.py` is the same
147	 * literal.
148	 */
149	// The combining range is deliberate and the lint's hazard does not arise. Its
150	// concern is a class that matches a combining mark *alone*, splitting a
151	// grapheme in two. Here the `+` takes maximal runs, so a base character and
152	// the marks that follow it are always taken together — which is the point: a
153	// decomposed "m" + U+0301 + "a" has to tokenise as one token and hash equal to
154	// the precomposed spelling. The alternation the rule suggests would also stop
155	// matching the Thai vowel signs, which legitimately follow their consonant.
156	// biome-ignore lint/suspicious/noMisleadingCharacterClass: see above
157	const TOKEN_PATTERN = /[0-9a-z\u00c0-\u024f\u0300-\u036f\u0e00-\u0e7f]+/g;
158	
159	/**
160	 * Text to comparison tokens.
161	 *
162	 * NFC first: the PDFs are inconsistent about precomposed versus decomposed
163	 * accents and hand-typed prose is inconsistent in the other direction, so
164	 * without it a decomposed "máa" fails to match a precomposed one.
165	 */
166	export function tokenize(text: string): string[] {
167		return text.normalize("NFC").toLowerCase().match(TOKEN_PATTERN) ?? [];
168	}
169	
170	/** Every overlapping window of `width` tokens, space-joined. */
171	export function ngramsOf(tokens: readonly string[], width: number): string[] {
172		const windows: string[] = [];
173		for (let i = 0; i + width <= tokens.length; i += 1) {
174			windows.push(tokens.slice(i, i + width).join(" "));
175		}
176		return windows;
177	}
178	
179	/** The artifact truncates digests to this many hex characters. */
180	const DIGEST_HEX_CHARS = 16;
181	
182	/**
183	 * Salted, truncated SHA-256 of one window — the mirror of `hash_ngram`.
184	 *
185	 * U+001F separates salt from payload because it cannot occur inside a token,
186	 * so no two salt/n-gram pairs can hash the same input. Web Crypto rather than
187	 * `node:crypto` keeps this module free of a Node builtin: it is domain code,
188	 * and the architecture has domain importing nothing outward.
189	 */
190	export async function hashNgram(salt: string, ngram: string): Promise<string> {
191		const payload = new TextEncoder().encode(`${salt}\u001f${ngram}`);
192		const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", payload));
193		return Array.from(digest.slice(0, DIGEST_HEX_CHARS / 2), (byte) =>
194			byte.toString(16).padStart(2, "0"),
195		).join("");
196	}
197	
198	function decodeSources(
199		flags: number,
200		sourceFlags: Readonly<Record<string, number>>,
201	): OriginalitySource[] {
202		return Object.entries(sourceFlags)
203			.filter(([, bit]) => (flags & bit) !== 0)
204			.map(([name]) => name as OriginalitySource);
205	}
206	
207	/**
208	 * Validate a corpus artifact, or say why it is unusable.
209	 *
210	 * Every rejection here is a case where the alternative is a gate that reports
211	 * "cleared" on material it never actually compared: an empty object, a
212	 * truncated write, an artifact built at a width this module does not query at,
213	 * or one missing a whole PDF set.
214	 */
215	export function loadOriginalityCorpus(raw: unknown): CorpusLoad {
216		if (typeof raw !== "object" || raw === null) {
217			return { reason: "corpus artifact is not an object" };
218		}
219		const artifact = raw as Partial<OriginalityCorpus>;
220	
221		if (typeof artifact.salt !== "string" || artifact.salt.length === 0) {
222			return { reason: "corpus artifact has no salt" };
223		}
224		if (artifact.ngramWidth !== NGRAM_WIDTH) {
225			return {
226				reason: `corpus was built at n=${String(artifact.ngramWidth)}, but this check queries n=${NGRAM_WIDTH}`,
227			};
228		}
229		if (
230			typeof artifact.ngrams !== "object" ||
231			artifact.ngrams === null ||
232			typeof artifact.sourceFlags !== "object" ||
233			artifact.sourceFlags === null
234		) {
235			return { reason: "corpus artifact is missing its n-gram table" };
236		}
237		const sourceFlags = artifact.sourceFlags;
238		if (Object.keys(artifact.ngrams).length === 0) {
239			return { reason: "corpus contains no n-grams" };
240		}
241		if (
242			typeof artifact.tokenCount !== "number" ||
243			artifact.tokenCount < MINIMUM_CORPUS_TOKENS
244		) {
245			return {
246				reason: `corpus holds ${String(artifact.tokenCount)} tokens, below the floor of ${MINIMUM_CORPUS_TOKENS}`,
247			};
248		}
249	
250		const present = new Set(
251			Object.values(artifact.ngrams).flatMap((flags) =>
252				decodeSources(flags, sourceFlags),
253			),
254		);
255		const missing = REQUIRED_CORPUS_SOURCES.filter((set) => !present.has(set));
256		if (missing.length > 0) {
257			return { reason: `corpus is missing source set(s): ${missing.join(", ")}` };
258		}
259	
260		return {
261			salt: artifact.salt,
262			ngramWidth: artifact.ngramWidth,
263			tokenCount: artifact.tokenCount,
264			ngrams: artifact.ngrams,
265			sourceFlags,
266		};
267	}
268	
269	/** The shipped corpus, validated once at import. */
270	export const shippedCorpus: CorpusLoad = loadOriginalityCorpus(corpusArtifact);
271	
272	/**
273	 * Does this candidate reuse a run of {@link NGRAM_WIDTH} tokens from the
274	 * licensed source?
275	 *
276	 * A candidate shorter than the window yields no comparisons and comes back
277	 * `cleared` with `ngramsChecked: 0` — there is nothing this measure can say
278	 * about a four-word phrase, and the count rides on the result so a caller can
279	 * see that rather than read a clearance it did not get.
280	 */
281	export async function checkOriginality(
282		candidate: string,
283		corpus: CorpusLoad = shippedCorpus,
284	): Promise<OriginalityResult> {
285		if (!isCorpusLoaded(corpus)) {
286			return { status: "not-checked", ngramsChecked: 0, reason: corpus.reason };
287		}
288	
289		const windows = ngramsOf(tokenize(candidate), NGRAM_WIDTH);
290		for (const [index, ngram] of windows.entries()) {
291			const flags = corpus.ngrams[await hashNgram(corpus.salt, ngram)];
292			if (flags !== undefined) {
293				return {
294					status: "overlapping",
295					ngramsChecked: index + 1,
296					overlap: { ngram, sources: decodeSources(flags, corpus.sourceFlags) },
297				};
298			}
299		}
300		return { status: "cleared", ngramsChecked: windows.length };
301	}
302	
303	/**
304	 * The loud form, for content tasks that want the gate to stop them.
305	 *
306	 * Throws on `overlapping` *and* on `not-checked`. The second is the point: a
307	 * corpus that failed to load must not be the reason a paraphrase shipped.
308	 */
309	export async function assertOriginal(
310		candidate: string,
311		corpus: CorpusLoad = shippedCorpus,
312	): Promise<void> {
313		const result = await checkOriginality(candidate, corpus);
314		if (result.status === "overlapping") {
315			throw new Error(
316				`originality: candidate reuses a ${NGRAM_WIDTH}-token run from ${result.overlap.sources.join(", ")}: "${result.overlap.ngram}"`,
317			);
318		}
319		if (result.status === "not-checked") {
320			throw new Error(`originality: not checked — ${result.reason}`);
321		}
322	}
